\operatorname{TyOK}_{CIC}(I,\mathcal I)
\Longleftrightarrow
\begin{array}{l}
\forall i<n\ \exists s_i\in\mathsf{Sort}_{CIC}\
(p_0:A_0,\ldots,p_{i-1}:A_{i-1})
\vdash_{CIC}^{\mathsf{pre}}
A_i:\operatorname{sort}(s_i)\\
{}\wedge\
\forall k<m\ \exists t_k\in\mathsf{Sort}_{CIC}\
(p_0:A_0,\ldots,p_{n-1}:A_{n-1})
\vdash_{CIC}^{\mathsf{pre}}
C_k:\operatorname{sort}(t_k),
\end{array}

\mathsf{PreIndForm}_{CIC}
=
\left\{
\left(
\operatorname{ParamJdgs}_{CIC}(\Gamma,\overline p,\overline A,\overline P),
\operatorname{jdg}_{CIC}
(\Gamma,\operatorname{ind}(I,\overline P),\operatorname{sort}(\mathsf s_I))
\right):
\begin{array}{l}
\operatorname{WFIndStr}_{CIC}(I,\mathcal I),\\
\mathcal I(I)=(\overline p,\overline A,\mathsf s_I,\overline c,\overline C),\\
\Gamma\in\mathsf{Ctx}_{CIC},\quad
|\overline P|=|\overline p|
\end{array}
\right\}.

\mathsf{IndForm}_{CIC}
=
\left(\left\{
\left(
\operatorname{ParamJdgs}_{CIC}(\Gamma,\overline p,\overline A,\overline P),
\operatorname{jdg}_{CIC}
(\Gamma,\operatorname{ind}(I,\overline P),\operatorname{sort}(\mathsf s_I))
\right):
\begin{array}{l}
\operatorname{WFInd}_{CIC}(I,\mathcal I),\\
\mathcal I(I)=(\overline p,\overline A,\mathsf s_I,\overline c,\overline C),\\
\Gamma\in\mathsf{Ctx}_{CIC},\
|\overline P|=|\overline p|
\end{array}
\right\}\right)\cap\left((\mathsf{Jdg}_{CIC})^{<\omega}\times\mathsf{Jdg}_{CIC}\right).

\mathsf{ConIntro}_{CIC}
=
\left(\left\{
\left(
\operatorname{ParamJdgs}_{CIC}(\Gamma,\overline p,\overline A,\overline P)
^\frown
\operatorname{SpineJdgs}_{CIC}
(\Gamma,C_k[\overline p:=\overline P],\overline M),
\operatorname{jdg}_{CIC}
\left(
\Gamma,
\operatorname{con}(c_k,\overline M),
\operatorname{SpineTy}_{CIC}
(C_k[\overline p:=\overline P],\overline M)
\right)
\right):
\begin{array}{l}
\operatorname{WFInd}_{CIC}(I,\mathcal I),\\
\mathcal I(I)=(\overline p,\overline A,\mathsf s_I,\overline c,\overline C),\\
k<|\overline c|,\
c_k=\overline c(k),\
C_k=\overline C(k),\\
\Gamma\in\mathsf{Ctx}_{CIC}
\end{array}
\right\}\right)\cap\left((\mathsf{Jdg}_{CIC})^{<\omega}\times\mathsf{Jdg}_{CIC}\right).

\mathsf{CaseElim}_{CIC}
=
\left(\left\{
\left(
\begin{array}{l}
\bigl\langle
\operatorname{jdg}_{CIC}(\Gamma,M,\operatorname{ind}(I,\overline P)),
\operatorname{jdg}_{CIC}
(\Gamma,Q,\operatorname{Motive}_{CIC}(I,\overline P,Q,s))
\bigr\rangle\\
\qquad^\frown
\operatorname{BranchJdgs}_{CIC}
(\Gamma,I,\overline P,Q,\overline f)
\end{array},
\operatorname{jdg}_{CIC}
(\Gamma,\operatorname{case}(I,Q,\overline f,M),\operatorname{app}(Q,M))
\right):
\begin{array}{l}
\operatorname{WFInd}_{CIC}(I,\mathcal I),\
\mathcal I(I)=(\overline p,\overline A,\mathsf s_I,\overline c,\overline C),\\
\Gamma\in\mathsf{Ctx}_{CIC},\
s\in\mathsf{Sort}_{CIC},\
|\overline f|=|\overline c|
\end{array}
\right\}\right)\cap\left((\mathsf{Jdg}_{CIC})^{<\omega}\times\mathsf{Jdg}_{CIC}\right).

\operatorname{bchild}_{CIC}(E,i)=
\begin{cases}
\{y\},&E=\operatorname{Pi}(y,A,B)\text{ 或 }E=\operatorname{lam}(y,A,B),\ i=1,\\
\{g,y\},&E=\operatorname{fix}(g,y,A,B),\ i=1,\\
\varnothing,&\text{其它合法子边}.
\end{cases}
